"""Endpoints for cross-domain recommendations generated by Analytics."""

from typing import Literal
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select, text

from app.auth.services import get_current_user
from app.common.models import COMMON_RESPONSES, ErrorMessage
from app.databases.analytics.recommendations_models import (
    AnalyticsRecommendation,
    AnalyticsRecommendationList,
    AnalyticsRecommendationPatch,
)
from database.connection import DatabaseConnection
from database.models.metadata.database import Database


router = APIRouter(
    prefix="/databases/{database_id}/analytics/recommendations",
    tags=["databases"],
    dependencies=[Depends(get_current_user)],
)


@router.get("", response_model=AnalyticsRecommendationList, responses=COMMON_RESPONSES)
async def list_recommendations(
    database_id: UUID,
    status: Literal["open", "dismissed", "resolved"] | None = Query(default=None),
):
    """List persisted Analytics recommendations for a database."""
    async with DatabaseConnection() as conn:
        database_result = await conn.execute(
            select(Database).where(Database.public_id == database_id, Database.deleted_at.is_(None))
        )
        database = database_result.scalar_one_or_none()
        if database is None:
            raise HTTPException(status_code=404, detail="Database not found")
        statement = """
            SELECT id, category, severity, confidence, title, summary, recommendation,
                   evidence, status, first_seen_at, last_seen_at
            FROM analytics.recommendation
            WHERE database_id = :database_id
        """
        params = {"database_id": database.id}
        if status is not None:
            statement += " AND status = :status"
            params["status"] = status
        statement += """
            ORDER BY CASE severity WHEN 'critical' THEN 3 WHEN 'warning' THEN 2 ELSE 1 END DESC,
                     last_seen_at DESC
        """
        result = await conn.execute(text(statement), params)
        items = [
            AnalyticsRecommendation(database_id=database_id, **dict(row))
            for row in result.mappings()
        ]
    return AnalyticsRecommendationList(database_id=database_id, items=items)


@router.patch("/{recommendation_id}", response_model=AnalyticsRecommendation, responses={**COMMON_RESPONSES, 404: {"model": ErrorMessage}})
async def patch_recommendation(
    database_id: UUID,
    recommendation_id: int,
    patch: AnalyticsRecommendationPatch,
):
    """Dismiss, resolve, or reopen a recommendation."""
    async with DatabaseConnection() as conn:
        database_result = await conn.execute(
            select(Database).where(Database.public_id == database_id, Database.deleted_at.is_(None))
        )
        database = database_result.scalar_one_or_none()
        if database is None:
            raise HTTPException(status_code=404, detail="Database not found")
        result = await conn.execute(text("""
            UPDATE analytics.recommendation SET status = :status
            WHERE id = :recommendation_id AND database_id = :database_id
            RETURNING id, category, severity, confidence, title, summary, recommendation,
                      evidence, status, first_seen_at, last_seen_at
        """), {"status": patch.status, "recommendation_id": recommendation_id, "database_id": database.id})
        row = result.mappings().one_or_none()
        if row is None:
            raise HTTPException(status_code=404, detail="Recommendation not found")
        await conn.commit()
    return AnalyticsRecommendation(database_id=database_id, **dict(row))
